+// Over the four lanes of a query (l, l ^ 16, l ^ 32, l ^ 48).
+__device__ __forceinline__ float qmax4(float v) {
+  v = fmaxf(v, __shfl_xor(v, 16));
+  return fmaxf(v, __shfl_xor(v, 32));
