+    const int* __restrict__ block_table, const int* __restrict__ q_to_req,
+    const int* __restrict__ q_to_klen, float* __restrict__ mid_o,
+    const int* __restrict__ k_signs, float sm_scale, int num_q, int num_q_heads,
